            "לסווג את החשיפה המשפטית: יש להפריד בין כלי פרודוקטיביות פנימיים, מערכות מול לקוחות, מערכות שמסייעות בקבלת החלטות, ומערכות שעלולות להשפיע על עובדים, אשראי, שירותים חיוניים, זכויות או הליכים ציבוריים.",
